python3 -c "
import ast, sys
VIOLATIONS = []
for path in sorted(__import__('glob').glob('src/security_review/**/*.py', recursive=True)):
    try:
        tree = ast.parse(open(path).read())
    except SyntaxError:
        continue
    for node in ast.walk(tree):
        if not isinstance(node, ast.ExceptHandler):
            continue
        body = node.body
        has_raise = any(isinstance(s, ast.Raise) for s in body)
        has_log = any(
            isinstance(s, ast.Expr) and isinstance(s.value, ast.Call)
            and any(kw in ast.dump(s.value) for kw in ['logger', 'log', 'warning', 'error', 'critical', 'debug'])
            for s in body
        )
        has_error_return = any(
            isinstance(s, ast.Return) and s.value and 'Error' in ast.dump(s.value)
            for s in body
        )
        if not has_raise and not has_log and not has_error_return:
            VIOLATIONS.append(f'  {path}:{node.lineno}: except block with no logging and no re-raise')
if VIOLATIONS:
    print('\\n'.join(VIOLATIONS))
    sys.exit(1)
"
